def process(roman_cities):
    import pandas as pd
    import numpy as np

    df = roman_cities.copy()
    col = 'Barrington Atlas Rank'

    def parse_rank(x):
        if pd.isna(x):
            return np.nan
        s = str(x).strip()
        if s == '' or s.lower() == 'nan':
            return np.nan
        # handle forms like '4 or 5'
        if 'or' in s:
            parts = [p.strip() for p in s.split('or')]
            nums = []
            for p in parts:
                try:
                    nums.append(float(p))
                except Exception:
                    # if not pure numeric, extract first numeric token
                    import re
                    m = re.search(r"[-+]?\d*\.?\d+", p)
                    if m:
                        nums.append(float(m.group()))
            if len(nums) == 0:
                return np.nan
            return float(np.mean(nums))
        # otherwise extract numeric
        import re
        m = re.search(r"[-+]?\d*\.?\d+", s)
        return float(m.group()) if m else np.nan

    df['rank_num'] = df[col].apply(parse_rank)
    # coords
    df['lat'] = pd.to_numeric(df['Latitude (Y)'], errors='coerce')
    df['lng'] = pd.to_numeric(df['Longitude (X)'], errors='coerce')
    return df

