def process(roman_modern_match):
    import numpy as np
    import pandas as pd

    df = roman_modern_match.copy()
    df = df[['rank_num','population']].dropna()
    # Need correlation between rank and population
    if len(df) < 2:
        return pd.DataFrame([{'corr': np.nan, 'n': len(df)}])
    corr = df['rank_num'].corr(df['population'])
    return pd.DataFrame([{'corr': float(corr), 'n': int(len(df))}])
